insert into official_sources (
 id,name,institution_name,institution_acronym,source_type,base_url,allowed_domains,allowed_path_prefixes,
 listing_urls,extraction_mode,audience_scope,geographic_scope,categories,priority,active,verification_status,crawl_interval_hours,notes
)
select id,name,institution,institution,source_type,url,domains,paths,array[url],'html',array['mixed'],coverage,categories,85,false,'pending',24,notes
from (values
('workintech-unicesumar-2026','WorkInTech e Hackathon — UniCesumar Maringá 2026','UniCesumar e Axion','corporate_organizer','https://www.workintech.com.br/',array['www.workintech.com.br']::text[],array['/']::text[],array['eventos','competicoes']::text[],array['PR']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade presencial na UniCesumar, em Maringá/PR. Workshops em 26 e 27/10; hackathon em 28, 29 e 30/10/2026, com equipes previstas de quatro a seis pessoas e avaliação por banca. Evento voltado a alunos de tecnologia; confirme vínculo e critérios de ingresso com a organização. Cadastro na plataforma do evento. Uma edição, incluindo os workshops e o hackathon; recrutamento anunciado não significa vaga de emprego garantida. Taxa de inscrição, remuneração e apoio financeiro não informados na página oficial. Consulte as condições da organização.'),
('connect-hackathon-7-2026','Hackathon Connect 7.0 — 2026','Connect Inovação','corporate_organizer','https://connectinovacao.com.br/hackathon/',array['connectinovacao.com.br']::text[],array['/hackathon/']::text[],array['eventos','competicoes']::text[],array['Brasil']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade híbrida: participação online ou presencial em hubs parceiros no Brasil, conforme vagas. Aberto a estudantes, profissionais, empreendedores, pesquisadores e interessados em inovação. Equipes de três a cinco pessoas para concorrer; inscrição individual permite procurar equipe. Menores de 18 anos precisam de autorização validada do responsável. Evento em 14/11/2026, das 9h às 21h; entrega das soluções às 21h de Brasília. Esse horário é de entrega, não prazo de inscrição. Confira o regulamento e o endereço do hub escolhido. Inscrição e participação gratuitas. Premiação sujeita às regras da organização; não há valor financeiro confirmado nesta ficha. Despesas pessoais de transporte, alimentação e hospedagem são do participante, salvo apoio expressamente anunciado pelo hub.'),
('obvc-2026','Olimpíada Brasileira de Vibe Coding — OBVC 2026','Organização da OBVC','corporate_organizer','https://obvc.com.br/',array['obvc.com.br']::text[],array['/']::text[],array['competicoes']::text[],array['Brasil']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade online, para brasileiros ou residentes no Brasil, conforme o regulamento. Categorias Universitária e Ampla na mesma edição. A Universitária exige comprovação de matrícula para avaliação. Cada inscrição corresponde a um projeto. Inscrições até 31/10/2026; envio do projeto até 01/11/2026, com interface em português brasileiro. Avaliação pela comissão; não é maratona cronometrada. Confira propriedade intelectual, critérios e condições no regulamento oficial. Inscrição paga: R$ 60,00 na Universitária e R$ 120,00 na Ampla. Cupom de universidade parceira pode reduzir a taxa, sujeito à elegibilidade. Prêmios variam com o número de inscrições válidas: até R$ 50.000,00 para o primeiro lugar da Universitária e até R$ 100.000,00 na Ampla. São tetos condicionais da escala de premiação, não valores garantidos, bolsa ou salário.'),
('soujava-november-2026','Encontro do SouJava — Novembro 2026','SouJava','corporate_organizer','https://encontros.soujava.org.br/talks/novembro-2026/',array['encontros.soujava.org.br']::text[],array['/talks/novembro-2026/']::text[],array['eventos']::text[],array['SP']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Encontro da comunidade Java, em parceria com Oracle Brasil, em 13/11/2026. Local presencial: Oracle, Rua Dr. José Áureo Bustamante, 455, São Paulo/SP. Palestras sobre agentes de IA, Java, RAG e refatoração. A descrição informa 18h30 e o calendário exibe horário convertido: consulte a organização para confirmar horário e acesso à transmissão; a ficha preserva somente a data. Reserva pela página oficial do encontro. Taxa de inscrição, remuneração e apoio financeiro não informados na página oficial. Consulte as condições da organização.'),
('mlh-builders-november-2026','Global Hack Week — Builders Week 2026','Major League Hacking','corporate_organizer','https://events.mlh.com/events/14729-global-hack-week-builders-week',array['events.mlh.com','ghw.mlh.com']::text[],array['/events/14729-global-hack-week-builders-week','/']::text[],array['eventos']::text[],array['Brasil','Mundo']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. De 6 a 12/11/2026. Modalidade online, em inglês, para estudantes e profissionais. Participação global, incluindo o Brasil. Menores de 13 a 18 anos precisam de permissão dos responsáveis. Exige conta MLH e aceite do código de conduta e das regras. Semana de desafios técnicos, projetos e encontros da comunidade; pontos e brindes condicionados às regras não equivalem a prêmio em dinheiro. Participação gratuita. Sem premiação em dinheiro confirmada nesta ficha; brindes e envio sujeitos às regras da MLH.'),
('mlh-open-source-december-2026','Global Hack Week — Open Source Week 2026','Major League Hacking','corporate_organizer','https://events.mlh.com/events/15199-global-hack-week-open-source-week',array['events.mlh.com','ghw.mlh.com']::text[],array['/events/15199-global-hack-week-open-source-week','/']::text[],array['eventos']::text[],array['Brasil','Mundo']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. De 4 a 10/12/2026. Modalidade online, em inglês, para estudantes e profissionais. Participação global, incluindo o Brasil. Menores de 13 a 18 anos precisam de permissão dos responsáveis. Exige conta MLH e aceite do código de conduta e das regras. Semana de desafios técnicos, projetos e encontros da comunidade; pontos e brindes condicionados às regras não equivalem a prêmio em dinheiro. Participação gratuita. Sem premiação em dinheiro confirmada nesta ficha; brindes e envio sujeitos às regras da MLH.'),
('devopsdays-florianopolis-2026','DevOpsDays Florianópolis 2026','Comunidade DevOpsDays Florianópolis','corporate_organizer','https://devopsdays.org/events/2026-florianopolis/welcome/',array['devopsdays.org']::text[],array['/events/2026-florianopolis/welcome/']::text[],array['eventos']::text[],array['SC']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade presencial, em 24/10/2026, no Centro Universitário Cesusc — UNICESUSC, SC-401, 9301, Florianópolis/SC. Conferência da comunidade DevOps, com conteúdo e troca de experiências. Inscrição pelo link de ingresso indicado na página oficial. Horários, disponibilidade e condições devem ser confirmados com a organização. Taxa de inscrição, remuneração e apoio financeiro não informados na página oficial. Consulte as condições da organização.'),
('devopsdays-recife-2026','DevOpsDays Recife 2026','Comunidade DevOpsDays Recife','corporate_organizer','https://devopsdays.org/events/2026-recife/welcome/',array['devopsdays.org']::text[],array['/events/2026-recife/welcome/']::text[],array['eventos']::text[],array['PE']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade presencial, em 12/12/2026, das 8h às 18h, na UNINASSAU Graças, Bloco B, Auditório Roque de Brito, Recife/PE. Conferência sobre cultura DevOps, automação, plataforma e segurança, para profissionais e interessados. Tema Rios, Pontes e Tecnologia. Ingresso pela plataforma indicada na página oficial; confirme disponibilidade e condições. Taxa de inscrição, remuneração e apoio financeiro não informados na página oficial. Consulte as condições da organização.'),
('enap-innovation-week-2026','Semana de Inovação — Enap 2026','Escola Nacional de Administração Pública — Enap','federal_government','https://semanadeinovacao.enap.gov.br/faq/',array['semanadeinovacao.enap.gov.br']::text[],array['/faq/']::text[],array['eventos']::text[],array['DF']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade híbrida, de 10 a 12/11/2026: presencial na Enap, Brasília/DF, e online via YouTube e Zoom. Inscrição única com escolha da modalidade; vagas presenciais limitadas. Inscrição geral não garante vaga em cada atividade, que exige reserva própria conforme lotação. Menores de 18 anos devem estar acompanhados dos responsáveis. Certificado conforme participação. O prazo encerrado para propostas de atividades não é o prazo de inscrição do público. Participação gratuita. Serviço opcional de acolhimento de crianças é cobrado pelo prestador. Viagem, hospedagem, alimentação e remuneração não anunciadas como apoio ao participante nesta página.'),
('recnplay-2026','REC’n’Play — Festival 2026','Organização do REC’n’Play','corporate_organizer','https://recnplay.pe/',array['recnplay.pe']::text[],array['/']::text[],array['eventos']::text[],array['PE']::text[],'Auditoria local 20/10/2026: references/source-audit-community-20261020.json. Fonte INATIVA e PENDENTE de verificação/ativação autorizada na VPS. Uma ficha por edição. Modalidade presencial, de 11 a 14/11/2026, em espaços do centro histórico do Recife/PE. Festival de inovação, tecnologia, criatividade e cultura, com oficinas, experiências e networking. Inscrição de participante pela plataforma indicada no site oficial; confira lotação, programação e regras de cada atividade. Voluntariado é outra seleção e não é uma vaga implícita nesta ficha. Festival com participação gratuita. Viagem, hospedagem, alimentação e remuneração não informadas como benefícios do participante na página consultada.')
) editions(id,name,institution,source_type,url,domains,paths,categories,coverage,notes)
on conflict(id) do nothing;
